query Environment($first: Float, $after: String, $commitsFirst2: Float, $commitsAfter2: String) {
  Environments(first: $first, after: $after) {
    edges {
      node {
        name
        uid
        project
        frameworkPreset
        gitBranch
        organizationUid
        outputDirectory
        serverCommand
        updatedAt
        updatedBy
        isProduction
        createdBy
        createdAt
        autoDeployOnPush
        buildCommand
        description
        hasLyticsEnabled
        passwordProtection {
          isEnabled
          password
          username
        }
        commits(first: $commitsFirst2, after: $commitsAfter2) {
          edges {
            node {
              author {
                name
                date
              }
              message
              sha
              url
            }
            cursor
          }
        }
      }
      cursor
    }
  }
}

query DeployHook($query: QueryDeployHooksInput!, $first: Float, $after: String) {
  deployHooks(query: $query, first: $first, after: $after) {
    edges {
      cursor
      node {
        createdBy
        environment
        name
        uid
        updatedAt
        updatedBy
        url
      }
    }
  }
}

mutation Mutation($deployHook: AddDeployHookInput!) {
  addDeployHook(deployHook: $deployHook) {
    url
    updatedBy
    updatedAt
    uid
    name
    environment
    createdBy
  }
}

mutation Mutation($deployHook: UpdateDeployHookInput!) {
  updateDeployHook(deployHook: $deployHook) {
    createdBy
    environment
    name
    uid
    updatedAt
    updatedBy
    url
  }
}

mutation DeleteDeployHook($deployHook: DeleteDeployHookInput!) {
  deleteDeployHook(deployHook: $deployHook) {
    createdBy
    environment
    name
    uid
    updatedAt
    updatedBy
    url
  }
}

mutation Mutation($revalidateCDNCache: RevalidateCDNCacheInput!) {
  revalidateCDNCache(revalidateCDNCache: $revalidateCDNCache) {
    autoDeployOnPush
    buildCommand
    createdAt
    createdBy
    description
    frameworkPreset
    gitBranch
    isProduction
    name
    outputDirectory
    project
    serverCommand
    uid
    updatedAt
    domains {
      edges {
        node {
          url
        }
      }
    }
  }
}
